    {
        "name": "Antibiotic-Associated Enterotoxemia",
        "name_ja": "抗生物質関連腸毒素血症",
        "symptoms": {"diarrhea", "lethargy", "appetite_loss", "dehydration", "bloated_abdomen", "hypothermia"},
        "description": "Antibiotic-Associated Enterotoxemia is a clinical condition requiring veterinary evaluation, diagnosis, and appropriate treatment.",
        "description_ja": "不適切な抗生物質（ペニシリン、アモキシシリン等）による致命的な腸内細菌叢の破壊です。",
        "urgency": "emergency",
        "recommended_tests": ["stool_culture", "blood_work", "physical_exam"],
        "causes": "Caused by administration of inappropriate antibiotics (penicillin, amoxicillin, erythromycin, lincomycin) that destroy normal cecal flora, allowing overgrowth of toxin-producing Clostridium difficile and E. coli.",
        "causes_ja": "モルモットにおける抗生物質関連腸毒素血症の原因: 不適切な抗生物質（ペニシリン、アモキシシリン等）による致命的な腸内細菌叢の破壊です。",
        "pathophysiology": "The pathological process involves tissue injury, inflammatory response, and progressive functional impairment. Without intervention, compensatory mechanisms may be overwhelmed, leading to clinical deterioration.",
        "pathophysiology_ja": "抗生物質関連腸毒素血症はモルモットにおける中毒性疾患である。有害物質の経口摂取、吸入、または経皮吸収により中毒障害が生じる。毒素は酵素阻害、受容体干渉、酸化的損傷、直接的な細胞毒性などの特定のメカニズムを通じて細胞プロセスを障害する。標的臓器は毒素により異なるが、肝臓（生体内変換）、腎臓（排泄）、神経系、消化管が一般的である。用量依存的に無症候性変化から劇症型臓器不全まで幅広い影響を及ぼす。",
        "treatment": "Treatment should be tailored to the specific condition and includes appropriate medical or surgical intervention, supportive care, pain management, and regular monitoring of treatment response.",
        "treatment_ja": "モルモットにおける抗生物質関連腸毒素血症の治療には迅速な除染と支持療法が必要である。摂取直後であれば催吐（種にとって安全な場合）または胃洗浄により吸収を低減する。活性炭は多くの毒素を吸着する。特異的解毒剤がある場合は投与する（例：抗凝固性殺鼠剤にビタミンK1、アセトアミノフェンにN-アセチルシステイン）。積極的な輸液療法で腎排泄を促進し灌流を維持する。臓器特異的障害（肝、腎、神経）をモニタリングし治療する。",
        "prevention": "Prevention includes appropriate husbandry, balanced nutrition, regular veterinary examinations, stress reduction, and prompt treatment of early signs of illness.",
        "prevention_ja": "抗生物質関連腸毒素血症の予防には有毒物質へのアクセス制限・除去、ペット安全な製品の使用、環境からの有毒植物の除去、薬剤・化学物質の適切な保管、屋外アクセス時の監視、種固有の中毒に関する飼い主教育が必要である。",
        "prognosis": "Prognosis depends on severity, underlying cause, and timeliness of treatment. Early aggressive intervention generally improves outcomes. Delayed presentation carries a guarded to poor prognosis.",
        "prognosis_ja": "抗生物質関連腸毒素血症の予後は適切な管理により一般的にやや良好〜良好である。早期診断された症例の多くは治療に良好に反応する。慢性例や再発例では長期管理が必要だが、概ね許容できるQOLを維持できる。定期的なモニタリングにより合併症の早期発見・対処が可能となる。",
        "onset_pattern": {"acute", "subacute"},
        "age_predisposition": {"adult", "puppy", "senior", "young"},
    },
