    {
        "name": "Barbering",
        "name_ja": "毛引き（バーバリング）",
        "symptoms": {"hair_loss", "patchy_fur", "stress_signs"},
        "description": "Barbering is a clinical condition requiring veterinary evaluation, diagnosis, and appropriate treatment.",
        "description_ja": "ストレス、退屈、支配関係によるケージメイトまたは自己による毛の咀嚼です。",
        "urgency": "low",
        "recommended_tests": ["physical_exam", "behavioral_assessment"],
        "causes": "A stress-related behavioral condition where guinea pigs chew their own or cagemates' fur. Contributing factors include inadequate space, improper social grouping, insufficient environmental enrichment, inappropriate diet, and handling stress.",
        "causes_ja": "皮膚機能に関連する不適応行動が原因。不十分なスペース・不適切な社会集団・不足した環境エンリッチメント・不適切な食事・取扱いストレスが寄与。モルモットの種特異的な運動・社会化・環境複雑性のニーズの充足が必要。",
        "pathophysiology": "The pathological process involves tissue injury, inflammatory response, and progressive functional impairment. Without intervention, compensatory mechanisms may be overwhelmed, leading to clinical deterioration.",
        "pathophysiology_ja": "モルモットの皮膚機能に影響する行動病理は、環境的・社会的・心理的ストレスに起因する。不適切な飼育環境が不適応行動を誘発する。慢性ストレスが視床下部-下垂体-副腎軸を活性化し、コルチゾール上昇・免疫抑制・二次的身体疾患をもたらす。モルモットの種特異的行動ニーズの充足が行動障害予防に不可欠。",
        "treatment": "Treatment should be tailored to the specific condition and includes appropriate medical or surgical intervention, supportive care, pain management, and regular monitoring of treatment response.",
        "treatment_ja": "モルモットにおける毛引きの治療は、原因に対する特異的療法と支持療法の組み合わせで行う。輸液療法・栄養支持・疼痛管理（種に適した鎮痛薬）・環境最適化が基本。特異的治療は診断に基づき、抗菌薬・駆虫薬・抗真菌薬・外科的介入・支持療法が含まれうる。エキゾチック動物専門獣医師への相談を推奨。",
        "prevention": "Prevention includes appropriate husbandry, balanced nutrition, regular veterinary examinations, stress reduction, and prompt treatment of early signs of illness.",
        "prevention_ja": "予防には適切な飼育管理（適切な食事・清潔な環境・最適な温湿度）；定期的な獣医師の健康診断；新規動物の検疫；ストレス軽減；種特異的予防措置が含まれる",
        "prognosis": "Prognosis depends on severity, timeliness of treatment, and response to therapy. Early intervention generally improves outcomes.",
        "prognosis_ja": "行動疾患の予後は原因の特定と環境改善の可能性に依存する。適切な環境エンリッチメントと飼育改善で多くの行動問題は改善する。慢性的な自傷行為や重度のストレス関連疾患は管理が困難。早期介入が予後改善に重要。",
        "onset_pattern": {"acute", "subacute"},
        "age_predisposition": {"adult", "puppy", "senior", "young"},
    },
