    {
        "name": "Lymphoma",
        "name_ja": "リンパ腫",
        "symptoms": {"weight_loss", "lethargy", "appetite_loss", "swollen_lymph_nodes", "labored_breathing"},
        "description": "Lymphoma is a neoplastic condition characterized by abnormal cell proliferation that may be benign or malignant.",
        "description_ja": "リンパ系の悪性腫瘍で、モルモットで最も一般的な腫瘍の一つです。",
        "urgency": "high",
        "recommended_tests": ["blood_work", "fine_needle_aspirate", "biopsy", "chest_x_ray"],
        "causes": "Neoplastic transformation from accumulated genetic mutations in oncogenes and tumor suppressor genes. Risk factors include age, chronic inflammation, viral infection, hormonal influences, UV exposure, and genetic predisposition.",
        "causes_ja": "モルモットにおけるリンパ腫の原因: 癌遺伝子・腫瘍抑制遺伝子の遺伝子変異蓄積による腫瘍性形質転換。加齢、慢性炎症、ウイルス感染、ホルモン影響、UV曝露、遺伝的素因がリスク因子。",
        "pathophysiology": "Lymphoma is a neoplastic condition. Lymphoma Neoplastic transformation occurs through accumulated genetic mutations in oncogenes, tumor suppressor genes, and DNA repair mechanisms. Uncontrolled cellular proliferation leads to tumor formation with potential for local tissue invasion and destruction. Malignant neoplasms may metastasize via lymphatic or hematogenous routes. Paraneoplastic syndromes—including hypercalcemia, cachexia, and immune dysregulation—may accompany the primary tumor and contribute to morbidity.",
        "pathophysiology_ja": "リンパ腫はモルモットにおける腫瘍性疾患である。癌遺伝子、腫瘍抑制遺伝子、DNA修復機構における遺伝子変異の蓄積により腫瘍性形質転換が生じる。制御不能な細胞増殖により腫瘍が形成され、局所組織への浸潤・破壊の可能性がある。悪性腫瘍はリンパ行性または血行性に転移しうる。高カルシウム血症、悪液質、免疫調節障害などの腫瘍随伴症候群が原発腫瘍に伴い、罹患率に寄与することがある。",
        "treatment": "Treatment of lymphoma in guinea pig depends on tumor type, location, and stage. Surgical excision with adequate margins is the primary treatment for accessible solid tumors. Chemotherapy may be indicated for systemic neoplasia, incompletely excised tumors, or metastatic disease. Radiation therapy can provide local tumor control. Palliative care focuses on pain management, nutritional support, and maintaining quality of life when curative treatment is not feasible.",
        "treatment_ja": "モルモットにおけるリンパ腫の治療は腫瘍の種類、部位、病期に依存する。アクセス可能な固形腫瘍には十分なマージンを確保した外科的切除が第一選択である。全身性腫瘍、不完全切除、転移性疾患には化学療法が適応となりうる。放射線療法は局所的な腫瘍制御を提供できる。根治療法が困難な場合は疼痛管理、栄養サポート、QOL維持に焦点を当てた緩和ケアを行う。",
        "prevention": "Prevention is limited for most neoplastic conditions. Regular health examinations facilitate early detection. Spaying/neutering may reduce risk of hormone-dependent tumors.",
        "prevention_ja": "リンパ腫の予防は限定的であるが、ホルモン依存性腫瘍軽減のための避妊・去勢手術、既知の発癌物質の回避、早期発見のための定期健診、適正体型の維持、該当する場合は遺伝的素因軽減のための責任ある繁殖が含まれる。",
        "prognosis": "",
        "prognosis_ja": "リンパ腫の予後は適切な管理により一般的にやや良好〜良好である。早期診断された症例の多くは治療に良好に反応する。慢性例や再発例では長期管理が必要だが、概ね許容できるQOLを維持できる。定期的なモニタリングにより合併症の早期発見・対処が可能となる。",
        "onset_pattern": {"chronic"},
        "age_predisposition": {"adult", "senior"},
    },
