    {
        "name": "Coccidia",
        "name_ja": "コクシジウム症",
        "symptoms": {"diarrhea", "weight_loss", "dehydration", "lethargy", "rough_coat"},
        "description": "Coccidia is a parasitic condition that causes clinical signs ranging from subclinical to severe systemic disease.",
        "description_ja": "原虫性の腸管寄生虫で、主に若いモルモットに影響します。",
        "urgency": "moderate",
        "recommended_tests": ["fecal_exam", "fecal_flotation"],
        "causes": "Protozoal intestinal parasite, primarily affects young guinea pigs.",
        "causes_ja": "モルモットにおけるコクシジウム症の原因: 原虫性の腸管寄生虫で、主に若いモルモットに影響します。",
        "pathophysiology": "Coccidia is a parasitic condition. Protozoal intestinal parasite, primarily affects young guinea pigs. The parasite establishes infection through ingestion, percutaneous penetration, or vector-mediated transmission. It exploits host resources for nutrition and reproduction while evading immune defenses through antigenic variation, immunomodulation, or intracellular sequestration. Tissue damage results from direct parasitic feeding, mechanical disruption, toxic metabolic byproducts, and the host's inflammatory and immune responses. Heavy parasite burdens can lead to anemia, malnutrition, organ dysfunction, and secondary infections.",
        "pathophysiology_ja": "コクシジウム症はモルモットにおける寄生虫疾患である。寄生虫は経口摂取、経皮的侵入、またはベクター媒介伝播を通じて感染を確立する。抗原変異、免疫調節、細胞内隔離により宿主の免疫防御を回避しながら、宿主の栄養と資源を利用して増殖する。組織損傷は寄生虫の直接的な摂食、機械的破壊、有毒代謝副産物、宿主の炎症・免疫応答に起因する。重度の寄生虫感染は貧血、栄養失調、臓器機能障害、二次感染を引き起こしうる。",
        "treatment": "Treatment of coccidia in guinea pig requires appropriate antiparasitic medication selected based on the specific parasite identified. Species-appropriate dosing is critical as some antiparasitics are toxic to certain species. Treatment may require multiple doses to eliminate all life stages. Environmental decontamination and in-contact animal treatment prevent reinfection. Supportive care addresses secondary complications such as anemia, dehydration, or malnutrition.",
        "treatment_ja": "モルモットにおけるコクシジウム症の治療には、同定された寄生虫に応じた適切な駆虫薬が必要である。一部の駆虫薬は特定の種に有毒であるため、種に適した用量設定が重要である。全てのライフステージを排除するため複数回投与が必要な場合がある。環境消毒と接触動物の治療で再感染を防止する。貧血、脱水、栄養失調などの二次的合併症に対する支持療法を行う。",
        "prevention": "Prevention includes regular parasite screening and treatment, environmental sanitation, quarantine of new animals, and avoiding overcrowding.",
        "prevention_ja": "コクシジウム症の予防には定期的な予防駆虫、環境衛生と糞便除去、新規動物の隔離・検査、ベクター防除、中間宿主や汚染環境への曝露回避が含まれる。",
        "prognosis": "",
        "prognosis_ja": "コクシジウム症の予後は適切な管理により一般的にやや良好〜良好である。早期診断された症例の多くは治療に良好に反応する。慢性例や再発例では長期管理が必要だが、概ね許容できるQOLを維持できる。定期的なモニタリングにより合併症の早期発見・対処が可能となる。",
        "onset_pattern": {"acute", "subacute"},
        "age_predisposition": {"adult", "puppy", "senior", "young"},
    },
