    {
        "name": "Bordetella Pneumonia",
        "name_ja": "ボルデテラ肺炎",
        "symptoms": {"appetite_loss", "coughing", "fever", "lethargy", "nasal_discharge", "respiratory_distress"},
        "description": "Bordetella Pneumonia is a respiratory condition affecting the airways or lungs, causing breathing difficulty.",
        "description_ja": "ボルデテラ・ブロンキセプティカによる重症肺炎で、しばしば致死的です。モルモットはこの菌に非常に感受性が高いです。",
        "urgency": "emergency",
        "recommended_tests": ["chest_xray", "tracheal_wash", "culture_sensitivity"],
        "causes": "Severe pneumonia caused by Bordetella bronchiseptica, often fatal. Guinea pigs are extremely susceptible to this organism.",
        "causes_ja": "モルモットにおけるボルデテラ肺炎の原因: ボルデテラ・ブロンキセプティカによる重症肺炎で、しばしば致死的です。モルモットはこの菌に非常に感受性が高いです。",
        "pathophysiology": "Severe pneumonia caused by Bordetella bronchiseptica, often fatal. Guinea pigs are extremely susceptible to this organism. Pathogenic bacteria colonize tissues through adhesion factors and invade via virulence mechanisms including toxin production, enzyme secretion, and immune evasion strategies. The resulting inflammatory cascade involves neutrophil infiltration, cytokine release, and complement activation. Tissue damage results from both direct bacterial action and the host's inflammatory response. Abscess formation, septicemia, or chronic granulomatous inflammation may develop depending on the organism and host immune status.",
        "pathophysiology_ja": "ボルデテラ肺炎はモルモットにおける細菌感染症である。病原菌は付着因子を通じて組織にコロニーを形成し、毒素産生、酵素分泌、免疫回避戦略などの病原性メカニズムを介して侵入する。好中球浸潤、サイトカイン放出、補体活性化を含む炎症カスケードが生じる。組織損傷は細菌の直接作用と宿主の炎症反応の両方に起因する。菌種と宿主の免疫状態に応じて、膿瘍形成、敗血症、または慢性肉芽腫性炎症が発生しうる。",
        "treatment": "Emergency stabilization with IV fluid therapy, oxygen supplementation, pain management, and treatment directed at the underlying cause. Intensive monitoring of vital parameters and organ function.",
        "treatment_ja": "モルモットにおけるボルデテラ肺炎の治療には、可能であれば培養感受性試験に基づく標的抗菌薬療法が必要である。結果待ちの間は経験的広域抗菌薬を開始する。抗菌薬治療期間は感染の排除と耐性予防に十分な期間とする。膿瘍や壊死組織には外科的排膿またはデブリードマンが必要な場合がある。支持療法として輸液、鎮痛薬、抗炎症薬、栄養サポートを行う。",
        "prevention": "Prevention includes appropriate husbandry, balanced nutrition, regular veterinary examinations, stress reduction, and prompt treatment of early signs of illness.",
        "prevention_ja": "ボルデテラ肺炎の予防には適切な衛生管理・消毒、利用可能なワクチン接種、創傷の迅速な処置、ストレス軽減、適切な換気、感染動物の隔離が含まれる。",
        "prognosis": "Prognosis depends on severity, underlying cause, and timeliness of treatment. Early aggressive intervention generally improves outcomes. Delayed presentation carries a guarded to poor prognosis.",
        "prognosis_ja": "ボルデテラ肺炎の予後は適切な管理により一般的にやや良好〜良好である。早期診断された症例の多くは治療に良好に反応する。慢性例や再発例では長期管理が必要だが、概ね許容できるQOLを維持できる。定期的なモニタリングにより合併症の早期発見・対処が可能となる。",
        "onset_pattern": {"acute", "subacute"},
        "age_predisposition": {"adult", "puppy", "senior", "young"},
    },
