    {
        "name": "Adenovirus Infection",
        "name_ja": "アデノウイルス感染症",
        "symptoms": {"appetite_loss", "lethargy", "nasal_discharge", "pneumonia", "sudden_death"},
        "description": "Adenovirus Infection is a viral disease that may cause acute or chronic illness with variable clinical presentation depending on host immunity and viral strain.",
        "description_ja": "モルモットに致死的な肺炎を引き起こすウイルス性呼吸器感染で、特に若齢や免疫不全の個体に多いです。",
        "urgency": "emergency",
        "recommended_tests": ["pcr_testing", "chest_xray", "blood_chemistry"],
        "causes": "Caused by viral infection; transmission occurs through direct contact, aerosol, fomites, or vertical transmission.",
        "causes_ja": "モルモットにおけるアデノウイルス感染症の原因: モルモットに致死的な肺炎を引き起こすウイルス性呼吸器感染で、特に若齢や免疫不全の個体に多いです。",
        "pathophysiology": "Bacterial organisms invade host tissues, triggering inflammatory cascades with neutrophil recruitment, cytokine release, and potential tissue necrosis. Systemic spread may lead to bacteremia and multi-organ dysfunction.",
        "pathophysiology_ja": "アデノウイルス感染症はモルモットにおけるウイルス感染症である。ウイルスは特定の受容体を介して宿主細胞に侵入し、細胞内機構を利用して複製する。直接的な細胞変性効果（細胞溶解、アポトーシス、標的臓器の組織壊死）を引き起こす。自然免疫（インターフェロン、NK細胞）および適応免疫（抗体、細胞性免疫）の宿主免疫応答が免疫病理に寄与することがある。ウイルス血症により病原体が複数の臓器系に播種される可能性があり、免疫抑制により二次的な細菌・真菌感染のリスクが高まる。",
        "treatment": "Treatment includes appropriate antimicrobial therapy based on culture and sensitivity, supportive care, fluid therapy, and surgical drainage if indicated. Monitor for treatment response and complications.",
        "treatment_ja": "モルモットにおけるアデノウイルス感染症の治療は主に支持療法であり、多くのウイルス感染症には特異的抗ウイルス薬がない。輸液療法により水分補給と電解質補正を行う。解熱鎮痛薬で発熱と不快感を管理する。広域抗菌薬で二次細菌感染を予防・治療する。食欲不振時の補助給餌を含む栄養サポートが不可欠である。免疫賦活剤やインターフェロンが有効な場合がある。感受性個体への伝播防止のため罹患個体を隔離する。",
        "prevention": "Prevention includes maintaining proper hygiene, appropriate husbandry, stress reduction, quarantine of new animals, and prompt treatment of wounds or primary conditions.",
        "prevention_ja": "アデノウイルス感染症の予防にはワクチン接種（利用可能な場合）、新規・病気動物の隔離、厳格なバイオセキュリティ対策、適切な消毒プロトコル、既知のキャリアや汚染環境との接触回避が含まれる。",
        "prognosis": "Variable depending on viral agent, host immunity, and promptness of supportive care. Some viral diseases carry high mortality, while others are self-limiting with supportive treatment.",
        "prognosis_ja": "アデノウイルス感染症の予後は適切な管理により一般的にやや良好〜良好である。早期診断された症例の多くは治療に良好に反応する。慢性例や再発例では長期管理が必要だが、概ね許容できるQOLを維持できる。定期的なモニタリングにより合併症の早期発見・対処が可能となる。",
        "onset_pattern": {"acute", "subacute"},
        "age_predisposition": {"adult", "puppy", "senior", "young"},
    },
