    {
        "name": "Calcium Phosphorus Imbalance",
        "name_ja": "カルシウム-リン不均衡",
        "symptoms": {"bone_pain", "lameness", "pathological_fracture", "teeth_problems", "weight_loss"},
        "description": "Calcium Phosphorus Imbalance is a nutritional or metabolic disorder caused by dietary imbalance or deficiency.",
        "description_ja": "食事中のカルシウムとリンの比率の不均衡による代謝性骨疾患と軟部組織石灰化です。",
        "urgency": "moderate",
        "recommended_tests": ["blood_chemistry", "xray", "diet_review"],
        "causes": "Dietary imbalance in calcium and phosphorus ratios leading to metabolite bone disease and soft tissue calcification.",
        "causes_ja": "モルモットにおけるカルシウム-リン不均衡の原因: 食事中のカルシウムとリンの比率の不均衡による代謝性骨疾患と軟部組織石灰化です。",
        "pathophysiology": "Calcium Phosphorus Imbalance is a metabolic/endocrine disorder. Dietary imbalance in calcium and phosphorus ratios leading to metabolite bone disease and soft tissue calcification. The underlying pathology involves dysregulation of hormonal feedback loops, enzyme activity, or substrate metabolism. This leads to imbalances in circulating hormone levels, electrolytes, or metabolic intermediates that affect cellular function across multiple organ systems. Compensatory mechanisms may temporarily maintain homeostasis but eventually decompensate, leading to progressive clinical deterioration and multi-organ effects.",
        "pathophysiology_ja": "カルシウム-リン不均衡はモルモットにおける代謝・内分泌疾患である。基礎病態はホルモンのフィードバックループ、酵素活性、または基質代謝の調節障害を伴う。循環ホルモン、電解質、代謝中間体のバランス異常が複数の臓器系にわたる細胞機能に影響を及ぼす。代償機構が一時的に恒常性を維持するが、最終的に代償不全に陥り、進行性の臨床的悪化と多臓器への影響を引き起こす。",
        "treatment": "",
        "treatment_ja": "モルモットにおけるカルシウム-リン不均衡の治療は基礎となるホルモン・代謝異常を標的とする。ホルモン補充療法または抑制療法により生理的バランスを回復する。食事療法で代謝疾患の栄養面に対処する。ホルモンレベル、血糖、電解質、臓器機能マーカーの定期的モニタリングにより用量調整を行う。二次的合併症（臓器障害、感染）の併行管理が不可欠である。長期または生涯にわたる治療が必要な場合がある。",
        "prevention": "Prevention includes providing a balanced, species-appropriate diet with adequate vitamins and minerals, appropriate UVB lighting where needed, and regular nutritional assessment.",
        "prevention_ja": "カルシウム-リン不均衡の予防には適切な食事設計、血液検査を含む定期的な健康モニタリング、健康体重の維持、過剰なおやつや不適切な食事の回避、無症候性変化の早期発見時の迅速な介入が含まれる。",
        "prognosis": "",
        "prognosis_ja": "カルシウム-リン不均衡の予後は適切な管理により一般的にやや良好〜良好である。早期診断された症例の多くは治療に良好に反応する。慢性例や再発例では長期管理が必要だが、概ね許容できるQOLを維持できる。定期的なモニタリングにより合併症の早期発見・対処が可能となる。",
        "onset_pattern": {"acute", "subacute"},
        "age_predisposition": {"adult", "puppy", "senior", "young"},
    },
