    {
        "name": "Bordetella - Subclinical Carrier",
        "name_ja": "ボルデテラ不顕性キャリア",
        "symptoms": {"sneezing", "nasal_discharge"},
        "description": "Bordetella - Subclinical Carrier is a clinical condition requiring veterinary evaluation, diagnosis, and appropriate treatment.",
        "description_ja": "感受性のあるモルモットに感染を広げる可能性のある無症候性ボルデテラキャリア。",
        "urgency": "low",
        "recommended_tests": ["nasal_culture", "pcr_testing"],
        "causes": "Asymptomatic Bordetella bronchiseptica carrier that can transmit to susceptible guinea pigs.",
        "causes_ja": "モルモットにおけるボルデテラ不顕性キャリアの原因: 感受性のあるモルモットに感染を広げる可能性のある無症候性ボルデテラキャリア。",
        "pathophysiology": "Asymptomatic Bordetella bronchiseptica carrier that can transmit to susceptible guinea pigs. Pathogenic bacteria colonize tissues through adhesion factors and invade via virulence mechanisms including toxin production, enzyme secretion, and immune evasion strategies. The resulting inflammatory cascade involves neutrophil infiltration, cytokine release, and complement activation. Tissue damage results from both direct bacterial action and the host's inflammatory response. Abscess formation, septicemia, or chronic granulomatous inflammation may develop depending on the organism and host immune status.",
        "pathophysiology_ja": "ボルデテラ不顕性キャリアはモルモットにおける細菌感染症である。病原菌は付着因子を通じて組織にコロニーを形成し、毒素産生、酵素分泌、免疫回避戦略などの病原性メカニズムを介して侵入する。好中球浸潤、サイトカイン放出、補体活性化を含む炎症カスケードが生じる。組織損傷は細菌の直接作用と宿主の炎症反応の両方に起因する。菌種と宿主の免疫状態に応じて、膿瘍形成、敗血症、または慢性肉芽腫性炎症が発生しうる。",
        "treatment": "",
        "treatment_ja": "モルモットにおけるボルデテラ不顕性キャリアの治療には、可能であれば培養感受性試験に基づく標的抗菌薬療法が必要である。結果待ちの間は経験的広域抗菌薬を開始する。抗菌薬治療期間は感染の排除と耐性予防に十分な期間とする。膿瘍や壊死組織には外科的排膿またはデブリードマンが必要な場合がある。支持療法として輸液、鎮痛薬、抗炎症薬、栄養サポートを行う。",
        "prevention": "Prevention of bordetella - subclinical carrier includes maintaining good hygiene and sanitation, appropriate vaccination where available, prompt treatment of wounds, stress reduction, proper ventilation, and quarantine of infected animals.",
        "prevention_ja": "ボルデテラ不顕性キャリアの予防には適切な衛生管理・消毒、利用可能なワクチン接種、創傷の迅速な処置、ストレス軽減、適切な換気、感染動物の隔離が含まれる。",
        "prognosis": "",
        "prognosis_ja": "ボルデテラ不顕性キャリアの予後は適切な管理により一般的にやや良好〜良好である。早期診断された症例の多くは治療に良好に反応する。慢性例や再発例では長期管理が必要だが、概ね許容できるQOLを維持できる。定期的なモニタリングにより合併症の早期発見・対処が可能となる。",
        "onset_pattern": {"acute", "subacute"},
        "age_predisposition": {"adult", "puppy", "senior", "young"},
    },
