    {
        "name": "Pregnancy Toxemia - Pre-partum",
        "name_ja": "妊娠中毒症（分娩前）",
        "symptoms": {"appetite_loss", "lethargy", "weakness", "collapse", "seizures"},
        "description": "Pregnancy Toxemia - Pre-partum is a clinical condition requiring veterinary evaluation, diagnosis, and appropriate treatment.",
        "description_ja": "妊娠後期の肥満雌に起こるケトーシスで、肝リピドーシスと急速な死亡を引き起こす。",
        "urgency": "emergency",
        "recommended_tests": ["blood_glucose", "blood_chemistry", "urinalysis"],
        "causes": "Ketosis in late-gestation obese sows causing hepatic lipidosis and rapid death.",
        "causes_ja": "モルモットにおける妊娠中毒症（分娩前）の原因: 妊娠後期の肥満雌に起こるケトーシスで、肝リピドーシスと急速な死亡を引き起こす。",
        "pathophysiology": "Pregnancy Toxemia - Pre-partum is a metabolic/endocrine disorder. Ketosis in late-gestation obese sows causing hepatic lipidosis and rapid death. The underlying pathology involves dysregulation of hormonal feedback loops, enzyme activity, or substrate metabolism. This leads to imbalances in circulating hormone levels, electrolytes, or metabolic intermediates that affect cellular function across multiple organ systems. Compensatory mechanisms may temporarily maintain homeostasis but eventually decompensate, leading to progressive clinical deterioration and multi-organ effects.",
        "pathophysiology_ja": "妊娠中毒症（分娩前）はモルモットにおける代謝・内分泌疾患である。基礎病態はホルモンのフィードバックループ、酵素活性、または基質代謝の調節障害を伴う。循環ホルモン、電解質、代謝中間体のバランス異常が複数の臓器系にわたる細胞機能に影響を及ぼす。代償機構が一時的に恒常性を維持するが、最終的に代償不全に陥り、進行性の臨床的悪化と多臓器への影響を引き起こす。",
        "treatment": "Emergency stabilization with IV fluid therapy, oxygen supplementation, pain management, and treatment directed at the underlying cause. Intensive monitoring of vital parameters and organ function.",
        "treatment_ja": "モルモットにおける妊娠中毒症（分娩前）の治療は基礎となるホルモン・代謝異常を標的とする。ホルモン補充療法または抑制療法により生理的バランスを回復する。食事療法で代謝疾患の栄養面に対処する。ホルモンレベル、血糖、電解質、臓器機能マーカーの定期的モニタリングにより用量調整を行う。二次的合併症（臓器障害、感染）の併行管理が不可欠である。長期または生涯にわたる治療が必要な場合がある。",
        "prevention": "Prevention of pregnancy toxemia - pre-partum includes appropriate diet formulation, regular health monitoring with blood work, maintaining healthy body weight, avoiding excessive treats or inappropriate foods, and early intervention when subclinical changes are detected.",
        "prevention_ja": "妊娠中毒症（分娩前）の予防には適切な食事設計、血液検査を含む定期的な健康モニタリング、健康体重の維持、過剰なおやつや不適切な食事の回避、無症候性変化の早期発見時の迅速な介入が含まれる。",
        "prognosis": "Prognosis depends on severity, underlying cause, and timeliness of treatment. Early aggressive intervention generally improves outcomes. Delayed presentation carries a guarded to poor prognosis.",
        "prognosis_ja": "妊娠中毒症（分娩前）の予後は適切な管理により一般的にやや良好〜良好である。早期診断された症例の多くは治療に良好に反応する。慢性例や再発例では長期管理が必要だが、概ね許容できるQOLを維持できる。定期的なモニタリングにより合併症の早期発見・対処が可能となる。",
        "onset_pattern": {"acute", "subacute"},
        "age_predisposition": {"adult", "puppy", "senior", "young"},
    },
