    {
        "name": "Urinary Sludge (Calcium Deposits)",
        "name_ja": "尿泥（カルシウム沈着）",
        "symptoms": {"straining_to_urinate", "blood_in_urine", "gritty_urine", "squealing_when_urinating"},
        "description": "Urinary Sludge (Calcium Deposits) is a nutritional or metabolic disorder caused by dietary imbalance or deficiency.",
        "description_ja": "膀胱にカルシウム豊富な沈殿物が蓄積し、刺激と有痛性排尿を引き起こす。",
        "urgency": "moderate",
        "recommended_tests": ["abdominal_x_ray", "urinalysis", "blood_work"],
        "causes": "Calcium-rich sediment accumulating in the bladder causing irritation and painful urination.",
        "causes_ja": "モルモットにおける尿泥（カルシウム沈着）の原因: 膀胱にカルシウム豊富な沈殿物が蓄積し、刺激と有痛性排尿を引き起こす。",
        "pathophysiology": "Urinary Sludge (Calcium Deposits) is a nutritional disorder. Calcium-rich sediment accumulating in the bladder causing irritation and painful urination. The condition results from inadequate intake, malabsorption, or excessive supplementation of specific nutrients. Deficiency states impair biochemical pathways dependent on the affected nutrient as cofactor or substrate, leading to cellular dysfunction. Excess states cause toxicity through accumulation in tissues or disruption of nutrient interactions. Species-specific dietary requirements make proper nutritional management critical for prevention.",
        "pathophysiology_ja": "尿泥（カルシウム沈着）はモルモットにおける栄養障害である。特定の栄養素の不十分な摂取、吸収不良、または過剰摂取により生じる。欠乏状態では、影響を受けた栄養素を補因子または基質として必要とする生化学的経路が障害され、細胞機能障害を引き起こす。過剰状態では組織への蓄積や栄養素間相互作用の障害により毒性が生じる。種特異的な食事要求により、適切な栄養管理が予防に不可欠である。",
        "treatment": "Treatment of urinary sludge (calcium deposits) in guinea pig centers on correcting the nutritional imbalance. Deficiency states require supplementation of the specific nutrient through dietary correction or therapeutic supplementation. Excess states require dietary restriction and supportive care for organ damage. Gradual correction prevents refeeding syndrome in malnourished animals. Species-specific dietary requirements must guide long-term nutritional planning. Regular reassessment ensures adequate without excessive intake.",
        "treatment_ja": "モルモットにおける尿泥（カルシウム沈着）の治療は栄養バランスの是正が中心となる。欠乏状態では食事の改善または治療的サプリメンテーションにより特定の栄養素を補充する。過剰状態では食事制限と臓器障害に対する支持療法を行う。栄養不良動物ではリフィーディング症候群予防のため段階的に是正する。種特異的な食事要求に基づく長期栄養計画を立案する。過不足のない摂取を確保するため定期的に再評価する。",
        "prevention": "Prevention includes providing a balanced, species-appropriate diet with adequate vitamins and minerals, appropriate UVB lighting where needed, and regular nutritional assessment.",
        "prevention_ja": "尿泥（カルシウム沈着）の予防には全ての栄養要求を満たす種に適した食事設計、単一食品のみの食事の回避、獣医師との定期的な食事内容の見直し、必要時の適切なサプリメンテーション、種固有の栄養ニーズに関する知識が必要である。",
        "prognosis": "",
        "prognosis_ja": "尿泥（カルシウム沈着）の予後は適切な管理により一般的にやや良好〜良好である。早期診断された症例の多くは治療に良好に反応する。慢性例や再発例では長期管理が必要だが、概ね許容できるQOLを維持できる。定期的なモニタリングにより合併症の早期発見・対処が可能となる。",
        "onset_pattern": {"acute", "subacute"},
        "age_predisposition": {"adult", "puppy", "senior", "young"},
    },
